baseline_program_module:
//! Native execution of a verified, finite subset of Lua 5.1 callbacks.
//!
//! Loading uses Lua to produce bytecode. Compilation binds object fields and
//! actions to a closed native schema, then discards all Lua handles. Programs
//! process new inputs and keep mutable scalar state between calls. Unsupported
//! operations fail compilation before any callback body is executed.
//!
//! Bindings describe semantics established by the host: object identities,
//! raw fields without metamethods, action identity/arity/results, and explicit
//! shared cells. The compiler cannot infer these promises from field names or
//! equal captured values. Hosts must validate them against their Lua objects.
//! These contracts must hold for every call, including action side effects.
//! Mutable captures must be private to one machine or explicitly shared group;
//! live Lua must not observe or change their former storage. A group binds
//! the same host-established cell indices across its programs. Actions cannot change
//! inputs or native cells indirectly, and must have the declared static return.
//! Mutable cells keep one fixed boolean or number type. String/number coercion,
//! dynamic lookup, object equality, loops and general Lua calls are unsupported.
//! An input frame is immutable for a complete call. Action arguments borrow
//! its bytes or the program's owned constants without allocating.

mod compile;
mod decode;

use crate::Function;
use std::{
    fmt,
    mem::{size_of, size_of_val},
    ops::{BitOr, BitOrAssign},
    sync::Arc,
};

/// A set of accepted native value types.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Types(u8);
impl Types {
    pub const NIL: Self = Self(1);
    pub const BOOLEAN: Self = Self(2);
    pub const NUMBER: Self = Self(4);
    pub const BYTES: Self = Self(8);
    pub const OBJECT: Self = Self(16);
    pub const ACTION: Self = Self(32);
    pub const ANY: Self = Self(63);
    const PRIMITIVE: Self = Self(15);
    fn accepts(self, actual: Self) -> bool {
        actual.0 != 0 && actual.0 & !self.0 == 0
    }
}
impl BitOr for Types {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        Self(self.0 | rhs.0)
    }
}
impl BitOrAssign for Types {
    fn bitor_assign(&mut self, rhs: Self) {
        self.0 |= rhs.0;
    }
}

/// Owned literal used while binding a program.
#[derive(Clone, Debug)]
pub enum Literal {
    Nil,
    Boolean(bool),
    Number(f64),
    Bytes(Box<[u8]>),
}

/// Initial value and fixed type of one explicit mutable cell.
#[derive(Clone, Copy, Debug)]
pub enum Cell {
    Boolean(bool),
    Number(f64),
}

/// Source of a parameter, capture or bound field.
#[derive(Clone, Debug)]
pub enum Binding {
    Literal(Literal),
    Object(u32),
    Cell(usize),
    Input { slot: usize, types: Types },
}

/// A host action with checked argument types and a statically known return.
/// Its effects must preserve the remaining bindings; native cells change only
/// through compiled writes. Action failures and dynamic results are unsupported.
#[derive(Clone, Debug)]
pub struct Action {
    pub tag: u32,
    pub parameters: Vec<Parameter>,
    /// None means no return values. Only literal and object bindings are accepted.
    pub result: Option<Binding>,
}

/// A host action's parameter contract. Object constraints preserve receiver
/// identity when lowering methods whose implementation depends on `self`.
#[derive(Clone, Copy, Debug)]
pub enum Parameter {
    Type(Types),
    Object(u32),
}

/// A field may be a value, a mutable cell, or a bound host action.
#[derive(Clone, Debug)]
pub enum FieldValue {
    Value(Binding),
    Action(Action),
}

/// A field of an opaque, host-validated object.
#[derive(Clone, Debug)]
pub struct Field {
    pub object: u32,
    pub name: Box<[u8]>,
    pub value: FieldValue,
}

/// Complete native schema for one callback. Repeated cell indices or object
/// identities express aliasing; distinct indices are never merged by value.
#[derive(Clone, Debug, Default)]
pub struct Bindings {
    pub arguments: Vec<Binding>,
    pub upvalues: Vec<Binding>,
    pub cells: Vec<Cell>,
    pub fields: Vec<Field>,
    pub environment: Option<u32>,
}

/// Rejection at compilation; no authored callback body has run.
#[derive(Debug)]
pub enum CompileError {
    InvalidChunk,
    InvalidBindings(&'static str),
    Unsupported { pc: usize, reason: &'static str },
    Dump(String),
}
impl fmt::Display for CompileError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "native Lua callback compilation: {self:?}")
    }
}
impl std::error::Error for CompileError {}

/// A malformed input frame. Compiled code and mutable state remain memory safe;
/// actions/state changes preceding the failing read are not rolled back.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RunError {
    MissingInput(usize),
    InputType(usize),
}
impl fmt::Display for RunError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "native Lua input: {self:?}")
    }
}
impl std::error::Error for RunError {}

/// Native inputs, results and action arguments. Opaque IDs refer to the host's
/// validated bindings, not Lua pointers. Byte slices may contain arbitrary data.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Datum<'a> {
    Nil,
    Boolean(bool),
    Number(f64),
    Bytes(&'a [u8]),
    Object(u32),
    Action(u32),
}
impl Datum<'_> {
    pub fn is_truthy(self) -> bool {
        !matches!(self, Self::Nil | Self::Boolean(false))
    }
    fn types(self) -> Types {
        match self {
            Self::Nil => Types::NIL,
            Self::Boolean(_) => Types::BOOLEAN,
            Self::Number(_) => Types::NUMBER,
            Self::Bytes(_) => Types::BYTES,
            Self::Object(_) => Types::OBJECT,
            Self::Action(_) => Types::ACTION,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Value {
    Nil,
    Boolean(bool),
    Number(u64),
    String(usize),
    InputString(usize),
    Object(u32),
    Action(u32),
}
impl Value {
    fn types(self) -> Types {
        match self {
            Self::Nil => Types::NIL,
            Self::Boolean(_) => Types::BOOLEAN,
            Self::Number(_) => Types::NUMBER,
            Self::String(_) | Self::InputString(_) => Types::BYTES,
            Self::Object(_) => Types::OBJECT,
            Self::Action(_) => Types::ACTION,
        }
    }
    fn truthy(self) -> bool {
        !matches!(self, Self::Nil | Self::Boolean(false))
    }
    fn number(self) -> f64 {
        let Self::Number(bits) = self else {
            unreachable!("verified numeric operand")
        };
        f64::from_bits(bits)
    }
}

#[derive(Clone, Copy, Debug)]
enum Source {
    Value(Value),
    Cell(usize),
    Input(usize, Types),
}
#[derive(Clone, Copy, Debug)]
enum Operand {
    Register(usize),
    Value(Value),
}
impl Operand {
    fn get(self, registers: &[Value]) -> Value {
        match self {
            Self::Register(r) => registers[r],
            Self::Value(v) => v,
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum Op {
    Unreachable,
    Load {
        dst: usize,
        source: Source,
        skip: bool,
    },
    Move {
        dst: usize,
        source: usize,
    },
    Nil {
        first: usize,
        last: usize,
    },
    Write {
        cell: usize,
        source: Operand,
    },
    Method {
        dst: usize,
        receiver: usize,
        action: u32,
    },
    Not {
        dst: usize,
        source: usize,
    },
    Neg {
        dst: usize,
        source: usize,
    },
    Arithmetic {
        dst: usize,
        left: Operand,
        right: Operand,
        operator: u8,
    },
    Compare {
        left: Operand,
        right: Operand,
        operator: u8,
        expected: bool,
    },
    Test {
        source: usize,
        expected: bool,
        copy: Option<usize>,
    },
    Jump(usize),
    Call {
        tag: u32,
        first: usize,
        count: usize,
        dst: Option<usize>,
        result: Value,
        tail: bool,
    },
    Return(Option<usize>),
}

struct Code {
    ops: Box<[Op]>,
    strings: Box<[Box<[u8]>]>,
    cells: Box<[Value]>,
    parameters: Box<[Source]>,
    registers: usize,
}

/// Immutable compiled callback. It contains Rust-owned code/data and no Lua
/// handle, registry reference, callback or state pointer.
#[derive(Clone)]
pub struct Program(Arc<Code>);
impl fmt::Debug for Program {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Program")
            .field("instructions", &self.0.ops.len())
            .field("cells", &self.0.cells.len())
            .finish()
    }
}

/// Compile a Lua closure using a validated native schema.
pub fn compile(function: &Function, bindings: &Bindings) -> Result<Program, CompileError> {
    if function.environment().is_none() {
        return Err(CompileError::Unsupported {
            pc: 0,
            reason: "native closure",
        });
    }
    let bytes = function
        .try_dump(false)
        .map_err(|error| CompileError::Dump(error.to_string()))?;
    compile_bytecode(&bytes, bindings)
}

/// Safely decode and compile a Lua 5.1 dump. These bytes are never loaded into
/// Lua. Headers and reachable operands/control flow are validated. Unsupported
/// opcodes and noncanonical constants are rejected.
pub fn compile_bytecode(bytes: &[u8], bindings: &Bindings) -> Result<Program, CompileError> {
    compile::lower(decode::decode(bytes)?, bindings)
}

impl Program {
    /// Create independent mutable state and reusable register storage.
    pub fn machine(&self) -> Machine {
        Machine {
            program: self.clone(),
            cells: self.0.cells.to_vec().into_boxed_slice(),
            registers: vec![Value::Nil; self.0.registers].into_boxed_slice(),
        }
    }

    /// Owned code/data payload, excluding allocator bookkeeping and Arc counters.
    pub fn retained_bytes(&self) -> usize {
        size_of::<Code>()
            + size_of_val(self.0.ops.as_ref())
            + size_of_val(self.0.cells.as_ref())
            + size_of_val(self.0.parameters.as_ref())
            + size_of_val(self.0.strings.as_ref())
            + self.0.strings.iter().map(|s| s.len()).sum::<usize>()
    }
}

/// A borrowed action argument view; it creates no intermediate collection.
pub struct Arguments<'a> {
    values: &'a [Value],
    code: &'a Code,
    inputs: &'a [Datum<'a>],
}
impl<'a> Arguments<'a> {
    pub fn len(&self) -> usize {
        self.values.len()
    }
    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }
    pub fn get(&self, index: usize) -> Option<Datum<'a>> {
        self.values.get(index).map(|v| datum(*v, self.code, self.inputs))
    }
}

/// A callback's explicit state and scratch space. Calls allocate no engine
/// storage; host actions may allocate according to the host's own policy.
pub struct Machine {
    program: Program,
    cells: Box<[Value]>,
    registers: Box<[Value]>,
}
impl Machine {
    /// Owned payload including code/data once; excludes allocator bookkeeping.
    pub fn retained_bytes(&self) -> usize {
        size_of::<Self>()
            + self.program.retained_bytes()
            + size_of_val(self.cells.as_ref())
            + size_of_val(self.registers.as_ref())
    }

    /// Observe a scalar cell without exposing mutable or Lua-backed storage.
    pub fn cell(&self, index: usize) -> Option<Datum<'_>> {
        self.cells.get(index).map(|v| datum(*v, &self.program.0, &[]))
    }

    /// Execute against actual immutable inputs and emit host actions in authored
    /// order. The result is the first returned value (nil for no results).
    pub fn run<'a>(
        &'a mut self,
        inputs: &'a [Datum<'a>],
        emit: impl FnMut(u32, Arguments<'_>),
    ) -> Result<Datum<'a>, RunError> {
        execute(
            &self.program.0,
            &mut self.cells,
            &mut self.registers,
            inputs,
            emit,
        )
    }
}

/// Programs with one explicit cell store and one reusable scratch buffer.
///
/// The host declares that identical cell indices refer to the same logical
/// storage across programs. Matching initial values do not prove aliasing.
/// Construction checks complete initial layouts, including numeric bits; the
/// host must establish identity and exclude observers outside this owner.
/// Programs execute in the order selected by the host. No Lua handles remain.
pub struct Group {
    programs: Box<[Program]>,
    cells: Box<[Value]>,
    registers: Box<[Value]>,
}

impl Group {
    /// Consume programs using the same host-established cell layout.
    pub fn new(programs: Vec<Program>) -> Result<Self, CompileError> {
        let initial = programs.first().map_or(&[][..], |p| p.0.cells.as_ref());
        if programs.iter().any(|p| p.0.cells.as_ref() != initial) {
            return Err(CompileError::InvalidBindings("shared cell layout"));
        }
        let cells = initial.to_vec().into_boxed_slice();
        let registers =
            vec![Value::Nil; programs.iter().map(|p| p.0.registers).max().unwrap_or(0)].into_boxed_slice();
        Ok(Self {
            programs: programs.into_boxed_slice(),
            cells,
            registers,
        })
    }

    pub fn len(&self) -> usize {
        self.programs.len()
    }
    pub fn is_empty(&self) -> bool {
        self.programs.is_empty()
    }

    /// Current scalar state; values and aliases are never merged by equality.
    pub fn cell(&self, index: usize) -> Option<Datum<'_>> {
        self.cells.get(index).map(|value| match *value {
            Value::Boolean(value) => Datum::Boolean(value),
            Value::Number(bits) => Datum::Number(f64::from_bits(bits)),
            _ => unreachable!("verified scalar cell"),
        })
    }

    /// Execute one program. None means an invalid program index and has no
    /// effects. Input errors retain preceding writes/actions, as in Machine.
    pub fn run<'a>(
        &'a mut self,
        index: usize,
        inputs: &'a [Datum<'a>],
        emit: impl FnMut(u32, Arguments<'_>),
    ) -> Option<Result<Datum<'a>, RunError>> {
        let program = self.programs.get(index)?;
        Some(execute(
            &program.0,
            &mut self.cells,
            &mut self.registers[..program.0.registers],
            inputs,
            emit,
        ))
    }

    /// Owned payload, counting shared program allocations once; allocator and
    /// Arc bookkeeping are excluded. This diagnostic does not allocate.
    pub fn retained_bytes(&self) -> usize {
        size_of::<Self>()
            + size_of_val(self.programs.as_ref())
            + size_of_val(self.cells.as_ref())
            + size_of_val(self.registers.as_ref())
            + self
                .programs
                .iter()
                .enumerate()
                .filter(|(index, program)| {
                    !self.programs[..*index]
                        .iter()
                        .any(|other| Arc::ptr_eq(&other.0, &program.0))
                })
                .map(|(_, program)| program.retained_bytes())
                .sum::<usize>()
    }
}

fn execute<'a>(
    code: &'a Code,
    cells: &mut [Value],
    registers: &mut [Value],
    inputs: &'a [Datum<'a>],
    mut emit: impl FnMut(u32, Arguments<'_>),
) -> Result<Datum<'a>, RunError> {
    registers.fill(Value::Nil);
    for (dst, source) in code.parameters.iter().enumerate() {
        registers[dst] = read(*source, cells, inputs)?;
    }
    let mut pc = 0;
    loop {
        let op = code.ops[pc];
        pc += 1;
        match op {
            Op::Unreachable => unreachable!("verified control flow"),
            Op::Load { dst, source, skip } => {
                registers[dst] = read(source, cells, inputs)?;
                pc += usize::from(skip);
            }
            Op::Move { dst, source } => registers[dst] = registers[source],
            Op::Nil { first, last } => registers[first..=last].fill(Value::Nil),
            Op::Write { cell, source } => cells[cell] = source.get(registers),
            Op::Method {
                dst,
                receiver,
                action,
            } => {
                let value = registers[receiver];
                registers[dst + 1] = value;
                registers[dst] = Value::Action(action);
            }
            Op::Not { dst, source } => registers[dst] = Value::Boolean(!registers[source].truthy()),
            Op::Neg { dst, source } => {
                registers[dst] = Value::Number((-registers[source].number()).to_bits())
            }
            Op::Arithmetic {
                dst,
                left,
                right,
                operator,
            } => {
                let (a, b) = (left.get(registers).number(), right.get(registers).number());
                registers[dst] = Value::Number(
                    match operator {
                        12 => a + b,
                        13 => a - b,
                        14 => a * b,
                        15 => a / b,
                        _ => unreachable!(),
                    }
                    .to_bits(),
                );
            }
            Op::Compare {
                left,
                right,
                operator,
                expected,
            } => {
                let (a, b) = (left.get(registers), right.get(registers));
                let equal = match operator {
                    23 => equal(a, b, code, inputs),
                    24 => a.number() < b.number(),
                    25 => a.number() <= b.number(),
                    _ => unreachable!(),
                };
                if equal != expected {
                    pc += 1;
                }
            }
            Op::Test {
                source,
                expected,
                copy,
            } => {
                if registers[source].truthy() == expected {
                    if let Some(dst) = copy {
                        registers[dst] = registers[source];
                    }
                } else {
                    pc += 1;
                }
            }
            Op::Jump(target) => pc = target,
            Op::Call {
                tag,
                first,
                count,
                dst,
                result,
                tail,
            } => {
                emit(
                    tag,
                    Arguments {
                        values: &registers[first..first + count],
                        code,
                        inputs,
                    },
                );
                if tail {
                    return Ok(datum(result, code, inputs));
                }
                if let Some(dst) = dst {
                    registers[dst] = result;
                }
            }
            Op::Return(source) => {
                return Ok(datum(source.map_or(Value::Nil, |i| registers[i]), code, inputs));
            }
        }
    }
}

fn read(source: Source, cells: &[Value], inputs: &[Datum<'_>]) -> Result<Value, RunError> {
    Ok(match source {
        Source::Value(v) => v,
        Source::Cell(i) => cells[i],
        Source::Input(i, expected) => {
            let v = *inputs.get(i).ok_or(RunError::MissingInput(i))?;
            if !expected.accepts(v.types()) {
                return Err(RunError::InputType(i));
            }
            match v {
                Datum::Nil => Value::Nil,
                Datum::Boolean(v) => Value::Boolean(v),
                Datum::Number(v) => Value::Number(v.to_bits()),
                Datum::Bytes(_) => Value::InputString(i),
                Datum::Object(_) | Datum::Action(_) => unreachable!("primitive input schema"),
            }
        }
    })
}

fn datum<'a>(v: Value, code: &'a Code, inputs: &'a [Datum<'a>]) -> Datum<'a> {
    match v {
        Value::Nil => Datum::Nil,
        Value::Boolean(v) => Datum::Boolean(v),
        Value::Number(bits) => Datum::Number(f64::from_bits(bits)),
        Value::String(i) => Datum::Bytes(&code.strings[i]),
        Value::InputString(i) => inputs[i],
        Value::Object(i) => Datum::Object(i),
        Value::Action(i) => Datum::Action(i),
    }
}

fn equal(a: Value, b: Value, code: &Code, inputs: &[Datum<'_>]) -> bool {
    match (datum(a, code, inputs), datum(b, code, inputs)) {
        (Datum::Nil, Datum::Nil) => true,
        (Datum::Boolean(a), Datum::Boolean(b)) => a == b,
        (Datum::Number(a), Datum::Number(b)) => a == b,
        (Datum::Bytes(a), Datum::Bytes(b)) => a == b,
        _ => false,
    }
}

baseline_program_lowering:
use super::decode::Prototype;
use super::*;
use std::borrow::Cow;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Symbol {
    Unknown,
    Constant(Value),
    Scalar(Types),
    Object(u32),
    Action(usize),
}
impl Symbol {
    fn types(self) -> Option<Types> {
        match self {
            Self::Unknown => None,
            Self::Constant(v) => Some(v.types()),
            Self::Scalar(t) => Some(t),
            Self::Object(_) => Some(Types::OBJECT),
            Self::Action(_) => Some(Types::ACTION),
        }
    }
    fn merge(self, other: Self) -> Self {
        if self == other {
            return self;
        }
        match (self.types(), other.types()) {
            (Some(a), Some(b)) if Types::PRIMITIVE.accepts(a | b) => Self::Scalar(a | b),
            _ => Self::Unknown,
        }
    }
}

#[derive(Clone, Copy)]
enum Resolved {
    Value(Source),
    Action(usize),
}
struct Call<'a> {
    tag: u32,
    parameters: &'a [Parameter],
    result: Value,
}
struct Builder<'a> {
    bindings: &'a Bindings,
    strings: Vec<Box<[u8]>>,
    cells: Vec<Value>,
    fields: Vec<Option<Resolved>>,
    actions: Vec<Call<'a>>,
}

impl Builder<'_> {
    fn literal(&mut self, literal: Literal) -> Value {
        match literal {
            Literal::Nil => Value::Nil,
            Literal::Boolean(v) => Value::Boolean(v),
            Literal::Number(v) => Value::Number(v.to_bits()),
            Literal::Bytes(v) => {
                let id = self.strings.len();
                self.strings.push(v);
                Value::String(id)
            }
        }
    }
    fn binding(&mut self, binding: &Binding) -> Result<Source, CompileError> {
        Ok(match binding {
            Binding::Literal(v) => Source::Value(self.literal(v.clone())),
            Binding::Object(id) => Source::Value(Value::Object(*id)),
            Binding::Cell(id) => {
                if *id >= self.cells.len() {
                    return Err(CompileError::InvalidBindings("cell index"));
                }
                Source::Cell(*id)
            }
            Binding::Input { slot, types } => {
                if !Types::PRIMITIVE.accepts(*types) {
                    return Err(CompileError::InvalidBindings("input type"));
                }
                Source::Input(*slot, *types)
            }
        })
    }
    fn symbol(&self, source: Source) -> Symbol {
        match source {
            Source::Value(Value::Object(id)) => Symbol::Object(id),
            Source::Value(v) => Symbol::Constant(v),
            Source::Cell(i) => Symbol::Scalar(self.cells[i].types()),
            Source::Input(_, types) => Symbol::Scalar(types),
        }
    }
    fn field(&mut self, object: Symbol, key: Symbol, pc: usize) -> Result<Resolved, CompileError> {
        let Symbol::Object(object) = object else {
            return Err(unsupported(pc, "dynamic object lookup"));
        };
        let Symbol::Constant(Value::String(key)) = key else {
            return Err(unsupported(pc, "dynamic field key"));
        };
        let index = self
            .bindings
            .fields
            .iter()
            .position(|field| field.object == object && field.name == self.strings[key])
            .ok_or_else(|| unsupported(pc, "unbound object field"))?;
        if let Some(field) = self.fields[index] {
            return Ok(field);
        }
        let bindings = self.bindings;
        let field = match &bindings.fields[index].value {
            FieldValue::Value(value) => Resolved::Value(self.binding(value)?),
            FieldValue::Action(action) => {
                if action.parameters.len() > 249
                    || action
                        .parameters
                        .iter()
                        .any(|t| matches!(t, Parameter::Type(Types(0))))
                {
                    return Err(CompileError::InvalidBindings("action parameters"));
                }
                let result = match &action.result {
                    None => Value::Nil,
                    Some(binding) => match self.binding(binding)? {
                        Source::Value(v) => v,
                        _ => return Err(CompileError::InvalidBindings("action result must be constant")),
                    },
                };
                let id = self.actions.len();
                if id > u32::MAX as usize {
                    return Err(CompileError::InvalidBindings("action count"));
                }
                self.actions.push(Call {
                    tag: action.tag,
                    parameters: &action.parameters,
                    result,
                });
                Resolved::Action(id)
            }
        };
        self.fields[index] = Some(field);
        Ok(field)
    }
    fn field_symbol(&self, field: Resolved) -> Symbol {
        match field {
            Resolved::Value(s) => self.symbol(s),
            Resolved::Action(id) => Symbol::Action(id),
        }
    }
    fn field_source(&self, field: Resolved) -> Source {
        match field {
            Resolved::Value(s) => s,
            Resolved::Action(id) => Source::Value(Value::Action(id as u32)),
        }
    }
    fn write(&self, target: Source, value: Symbol, pc: usize) -> Result<usize, CompileError> {
        let Source::Cell(index) = target else {
            return Err(unsupported(pc, "write to unbound cell"));
        };
        if !value
            .types()
            .is_some_and(|t| self.cells[index].types().accepts(t))
        {
            return Err(unsupported(pc, "cell type change"));
        }
        Ok(index)
    }
}

fn unsupported(pc: usize, reason: &'static str) -> CompileError {
    CompileError::Unsupported { pc, reason }
}
fn reg(symbols: &[Symbol], index: usize, pc: usize) -> Result<Symbol, CompileError> {
    let value = *symbols.get(index).ok_or(CompileError::InvalidChunk)?;
    if value == Symbol::Unknown {
        return Err(unsupported(pc, "unproven register value"));
    }
    Ok(value)
}
fn set(symbols: &mut [Symbol], index: usize, value: Symbol) -> Result<(), CompileError> {
    *symbols.get_mut(index).ok_or(CompileError::InvalidChunk)? = value;
    Ok(())
}
fn rk(
    symbols: &[Symbol],
    constants: &[Value],
    index: usize,
    pc: usize,
) -> Result<(Operand, Symbol), CompileError> {
    if index & 256 != 0 {
        let value = *constants.get(index & 255).ok_or(CompileError::InvalidChunk)?;
        Ok((Operand::Value(value), Symbol::Constant(value)))
    } else {
        Ok((Operand::Register(index), reg(symbols, index, pc)?))
    }
}
fn require(symbol: Symbol, types: Types, pc: usize) -> Result<(), CompileError> {
    if symbol.types().is_some_and(|actual| types.accepts(actual)) {
        Ok(())
    } else {
        Err(unsupported(pc, "operand coercion or metamethod"))
    }
}
fn edge(
    states: &mut [Option<Vec<Symbol>>],
    from: usize,
    target: usize,
    symbols: Cow<'_, [Symbol]>,
) -> Result<(), CompileError> {
    if target <= from {
        return Err(unsupported(from, "backward control flow"));
    }
    let state = states.get_mut(target).ok_or(CompileError::InvalidChunk)?;
    match state {
        None => *state = Some(symbols.into_owned()),
        Some(state) => {
            for (old, new) in state.iter_mut().zip(symbols.iter()) {
                *old = old.merge(*new);
            }
        }
    }
    Ok(())
}

pub(super) fn lower(prototype: Prototype<'_>, bindings: &Bindings) -> Result<Program, CompileError> {
    if prototype.upvalues != bindings.upvalues.len() {
        return Err(CompileError::InvalidBindings("upvalue count"));
    }
    for (index, field) in bindings.fields.iter().enumerate() {
        if bindings.fields[..index]
            .iter()
            .any(|f| f.object == field.object && f.name == field.name)
        {
            return Err(CompileError::InvalidBindings("duplicate object field"));
        }
    }
    let cells = bindings
        .cells
        .iter()
        .map(|c| match c {
            Cell::Boolean(v) => Value::Boolean(*v),
            Cell::Number(v) => Value::Number(v.to_bits()),
        })
        .collect();
    let mut builder = Builder {
        bindings,
        strings: Vec::new(),
        cells,
        fields: vec![None; bindings.fields.len()],
        actions: Vec::new(),
    };
    let constants: Vec<_> = prototype
        .constants
        .into_iter()
        .map(|v| builder.literal(v))
        .collect();
    let upvalues = bindings
        .upvalues
        .iter()
        .map(|v| builder.binding(v))
        .collect::<Result<Vec<_>, _>>()?;
    let mut parameters = Vec::with_capacity(prototype.parameters);
    // Lua 5.1 clears non-parameter registers on entry and can omit LOADNIL.
    let mut first = vec![Symbol::Constant(Value::Nil); prototype.registers];
    for (index, symbol) in first.iter_mut().take(prototype.parameters).enumerate() {
        let source = match bindings.arguments.get(index) {
            Some(v) => builder.binding(v)?,
            None => Source::Value(Value::Nil),
        };
        *symbol = builder.symbol(source);
        parameters.push(source);
    }
    let mut states = vec![None; prototype.code.len()];
    states[0] = Some(first);
    let mut ops = vec![Op::Unreachable; prototype.code.len()];
    for (pc, word) in prototype.code.into_iter().enumerate() {
        let opcode = (word & 63) as u8;
        if !matches!(opcode,0..=9|11..=15|18|19|22..=30) {
            return Err(unsupported(pc, "opcode"));
        }
        let Some(mut symbols) = states[pc].take() else {
            continue;
        };
        let a = ((word >> 6) & 255) as usize;
        let c = ((word >> 14) & 511) as usize;
        let b = ((word >> 23) & 511) as usize;
        let bx = ((word >> 14) & 262143) as usize;
        let mut next = Some(pc + 1);
        ops[pc] = match opcode {
            0 => {
                let v = reg(&symbols, b, pc)?;
                set(&mut symbols, a, v)?;
                Op::Move { dst: a, source: b }
            }
            1 => {
                let v = *constants.get(bx).ok_or(CompileError::InvalidChunk)?;
                set(&mut symbols, a, Symbol::Constant(v))?;
                Op::Load {
                    dst: a,
                    source: Source::Value(v),
                    skip: false,
                }
            }
            2 => {
                if b > 1 || c > 1 {
                    return Err(CompileError::InvalidChunk);
                }
                let v = Value::Boolean(b != 0);
                set(&mut symbols, a, Symbol::Constant(v))?;
                if c != 0 {
                    next = Some(pc + 2);
                }
                Op::Load {
                    dst: a,
                    source: Source::Value(v),
                    skip: c != 0,
                }
            }
            3 => {
                if b < a || b >= symbols.len() {
                    return Err(CompileError::InvalidChunk);
                }
                symbols[a..=b].fill(Symbol::Constant(Value::Nil));
                Op::Nil { first: a, last: b }
            }
            4 => {
                let source = *upvalues.get(b).ok_or(CompileError::InvalidChunk)?;
                set(&mut symbols, a, builder.symbol(source))?;
                Op::Load {
                    dst: a,
                    source,
                    skip: false,
                }
            }
            5 | 6 => {
                let (object, key) = if opcode == 5 {
                    let object = bindings
                        .environment
                        .ok_or_else(|| unsupported(pc, "unbound environment"))?;
                    (
                        Symbol::Object(object),
                        Symbol::Constant(*constants.get(bx).ok_or(CompileError::InvalidChunk)?),
                    )
                } else {
                    (reg(&symbols, b, pc)?, rk(&symbols, &constants, c, pc)?.1)
                };
                let field = builder.field(object, key, pc)?;
                set(&mut symbols, a, builder.field_symbol(field))?;
                Op::Load {
                    dst: a,
                    source: builder.field_source(field),
                    skip: false,
                }
            }
            7 | 8 | 9 => {
                let (target, source, symbol) = if opcode == 8 {
                    (
                        *upvalues.get(b).ok_or(CompileError::InvalidChunk)?,
                        Operand::Register(a),
                        reg(&symbols, a, pc)?,
                    )
                } else {
                    let (object, key, source, symbol) = if opcode == 7 {
                        let object = bindings
                            .environment
                            .ok_or_else(|| unsupported(pc, "unbound environment"))?;
                        (
                            Symbol::Object(object),
                            Symbol::Constant(*constants.get(bx).ok_or(CompileError::InvalidChunk)?),
                            Operand::Register(a),
                            reg(&symbols, a, pc)?,
                        )
                    } else {
                        let (source, symbol) = rk(&symbols, &constants, c, pc)?;
                        (
                            reg(&symbols, a, pc)?,
                            rk(&symbols, &constants, b, pc)?.1,
                            source,
                            symbol,
                        )
                    };
                    let field = builder.field(object, key, pc)?;
                    (builder.field_source(field), source, symbol)
                };
                let cell = builder.write(target, symbol, pc)?;
                Op::Write { cell, source }
            }
            11 => {
                let receiver = reg(&symbols, b, pc)?;
                let field = builder.field(receiver, rk(&symbols, &constants, c, pc)?.1, pc)?;
                let Resolved::Action(action) = field else {
                    return Err(unsupported(pc, "unbound method"));
                };
                set(&mut symbols, a + 1, receiver)?;
                set(&mut symbols, a, Symbol::Action(action))?;
                Op::Method {
                    dst: a,
                    receiver: b,
                    action: action as u32,
                }
            }
            12..=15 => {
                let (left, lt) = rk(&symbols, &constants, b, pc)?;
                let (right, rt) = rk(&symbols, &constants, c, pc)?;
                require(lt, Types::NUMBER, pc)?;
                require(rt, Types::NUMBER, pc)?;
                set(&mut symbols, a, Symbol::Scalar(Types::NUMBER))?;
                Op::Arithmetic {
                    dst: a,
                    left,
                    right,
                    operator: opcode,
                }
            }
            18 => {
                require(reg(&symbols, b, pc)?, Types::NUMBER, pc)?;
                set(&mut symbols, a, Symbol::Scalar(Types::NUMBER))?;
                Op::Neg { dst: a, source: b }
            }
            19 => {
                reg(&symbols, b, pc)?;
                set(&mut symbols, a, Symbol::Scalar(Types::BOOLEAN))?;
                Op::Not { dst: a, source: b }
            }
            22 => {
                let target = (pc as isize + 1 + bx as isize - 131071)
                    .try_into()
                    .map_err(|_| CompileError::InvalidChunk)?;
                next = Some(target);
                Op::Jump(target)
            }
            23..=25 => {
                if a > 1 {
                    return Err(CompileError::InvalidChunk);
                }
                let (left, lt) = rk(&symbols, &constants, b, pc)?;
                let (right, rt) = rk(&symbols, &constants, c, pc)?;
                let types = if opcode == 23 {
                    Types::PRIMITIVE
                } else {
                    Types::NUMBER
                };
                require(lt, types, pc)?;
                require(rt, types, pc)?;
                edge(&mut states, pc, pc + 2, Cow::Borrowed(&symbols))?;
                Op::Compare {
                    left,
                    right,
                    operator: opcode,
                    expected: a != 0,
                }
            }
            26 | 27 => {
                if c > 1 {
                    return Err(CompileError::InvalidChunk);
                }
                let source = if opcode == 26 { a } else { b };
                let value = reg(&symbols, source, pc)?;
                edge(&mut states, pc, pc + 2, Cow::Borrowed(&symbols))?;
                if opcode == 27 {
                    set(&mut symbols, a, value)?;
                }
                Op::Test {
                    source,
                    expected: c != 0,
                    copy: (opcode == 27).then_some(a),
                }
            }
            28 | 29 => {
                if b == 0 || (opcode == 28 && !matches!(c, 1 | 2)) {
                    return Err(unsupported(pc, "variable call arity"));
                }
                let Symbol::Action(id) = reg(&symbols, a, pc)? else {
                    return Err(unsupported(pc, "unbound call target"));
                };
                let call = &builder.actions[id];
                if b - 1 != call.parameters.len() {
                    return Err(unsupported(pc, "action arity"));
                }
                for (offset, parameter) in call.parameters.iter().enumerate() {
                    let symbol = reg(&symbols, a + 1 + offset, pc)?;
                    match *parameter {
                        Parameter::Type(types) => require(symbol, types, pc)?,
                        Parameter::Object(id) if symbol == Symbol::Object(id) => {}
                        Parameter::Object(_) => return Err(unsupported(pc, "unproven action receiver")),
                    }
                }
                let dst = (opcode == 28 && c == 2).then_some(a);
                if let Some(dst) = dst {
                    set(
                        &mut symbols,
                        dst,
                        match call.result {
                            Value::Object(i) => Symbol::Object(i),
                            v => Symbol::Constant(v),
                        },
                    )?;
                }
                if opcode == 29 {
                    next = None;
                }
                Op::Call {
                    tag: call.tag,
                    first: a + 1,
                    count: b - 1,
                    dst,
                    result: call.result,
                    tail: opcode == 29,
                }
            }
            30 => {
                if b == 0 {
                    return Err(unsupported(pc, "variable return arity"));
                }
                if b > 1 {
                    for index in a..a + b - 1 {
                        reg(&symbols, index, pc)?;
                    }
                }
                next = None;
                Op::Return((b > 1).then_some(a))
            }
            _ => unreachable!(),
        };
        if let Some(target) = next {
            edge(&mut states, pc, target, Cow::Owned(symbols))?;
        }
    }
    Ok(Program(Arc::new(Code {
        ops: ops.into_boxed_slice(),
        strings: builder.strings.into_boxed_slice(),
        cells: builder.cells.into_boxed_slice(),
        parameters: parameters.into_boxed_slice(),
        registers: prototype.registers,
    })))
}

